{"implementation": "def solve(case):
    nodes = case["nodes"]
    core_distance = case["core_distance"]
    distances = case["distances"]

    # Validate required fields
    if not isinstance(nodes, list) or len(nodes) < 2:
        raise ValueError("Invalid or insufficient nodes")
    if not isinstance(core_distance, dict):
        raise ValueError("core_distance must be a dict")
    if not isinstance(distances, list):
        raise ValueError("distances must be a list")
    for n in nodes:
        if n not in core_distance:
            raise ValueError(f"Missing core_distance for node {n}")

    # Compute mutual reachability for each pair, canonicalizing endpoints
    mr_edges = []
    for edge in distances:
        u, v, d = edge[0], edge[1], edge[2]
        if u not in core_distance:
            raise ValueError(f"Unknown node in distances: {u}")
        if v not in core_distance:
            raise ValueError(f"Unknown node in distances: {v}")
        mr = max(core_distance[u], core_distance[v], d)
        # Canonicalize undirected endpoints: lexicographically smaller first
        if u > v:
            u, v = v, u
        mr_edges.append((mr, u, v))

    # Sort by mutual reachability weight, then by endpoint IDs for determinism
    mr_edges.sort(key=lambda e: (e[0], e[1], e[2]))

    # Kruskal's MST with union-find
    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            rx, ry = ry, rx
        parent[ry] = rx
        if rank[rx] == rank[ry]:
            rank[rx] += 1
        return True

    mst_edges = []
    total_weight = 0.0
    n = len(nodes)

    for mr, u, v in mr_edges:
        if union(u, v):
            mst_edges.append([u, v, mr])
            total_weight += mr
            if len(mst_edges) == n - 1:
                break

    if len(mst_edges) != n - 1:
        raise ValueError("Graph is disconnected; MST cannot span all nodes")

    return {
        "mst_edges": mst_edges,
        "total_weight": total_weight
    }
"}
